from pathlib import Path
p=Path('packages/persistence/src/priority-national-source-coverage.ts')
s=p.read_text()
m='const CIPO: Authority = {'
assert m in s
b='''const MYIPO_MY: Authority = {\n  jurisdiction: "MY",\n  authorityName: "Intellectual Property Corporation of Malaysia (MyIPO)",\n  languages: ["ms-MY", "en"],\n  verificationEvidenceUri: "https://www.myipo.gov.my/",\n};\n\nexport const MYIPO_MY_SOURCE_COVERAGE_TARGETS = [\n  target(MYIPO_MY, {\n    id: "my-myipo-trademarks",\n    family: "PORTAL",\n    displayName: "Malaysia MyIPO Trademark Portal",\n    canonicalUri: "https://www.myipo.gov.my/public/",\n    entrypoints: [\n      { uri: "https://www.myipo.gov.my/", label: "MyIPO official portal" },\n      { uri: "https://www.myipo.gov.my/public/", label: "Public trademark services hub" },\n    ],\n    verificationEvidenceUri: "https://www.myipo.gov.my/",\n    notes: "MyIPO's public portal exposes Malaysia's trademark filing, management, forms and fees, legislation, search and Trademark Journal services.",\n  }),\n  target(MYIPO_MY, {\n    id: "my-myipo-trademark-filing",\n    family: "FILING",\n    displayName: "Malaysia MyIPO Trademark Filing and Application Guidance",\n    canonicalUri: "https://www.myipo.gov.my/applying-for-a-trademark/",\n    mode: "MIXED",\n    renderJavascriptHint: true,\n    verificationEvidenceUri: "https://www.myipo.gov.my/applying-for-a-trademark/",\n    notes: "MyIPO publishes the national application workflow and links IP Online Search & Filing, including preliminary advice/search and trademark application filing.",\n  }),\n  target(MYIPO_MY, {\n    id: "my-myipo-trademark-search",\n    family: "SEARCH",\n    displayName: "Malaysia MyIPO Trademark Search",\n    canonicalUri: "https://www.myipo.gov.my/search-trademark/",\n    mode: "MIXED",\n    renderJavascriptHint: true,\n    expectedArtifactKinds: ["HTML", "JSON"],\n    verificationEvidenceUri: "https://www.myipo.gov.my/search-trademark/",\n    notes: "MyIPO maintains a dedicated national trademark-search gateway and directs users to IP Online while also linking WIPO and ASEAN search surfaces.",\n  }),\n  target(MYIPO_MY, {\n    id: "my-myipo-trademark-fees",\n    family: "FEES",\n    displayName: "Malaysia MyIPO Trademark Forms and Fees",\n    canonicalUri: "https://www.myipo.gov.my/trademark-forms-and-fees/",\n    fetchAttachmentsHint: true,\n    expectedArtifactKinds: ["HTML", "MARKDOWN", "PDF"],\n    verificationEvidenceUri: "https://www.myipo.gov.my/trademark-forms-and-fees/",\n    notes: "MyIPO publishes current trademark forms and transaction-specific fee evidence under the Trademarks Act 2019 and Regulations; amounts remain sourced evidence rather than frozen catalog truth.",\n  }),\n  target(MYIPO_MY, {\n    id: "my-myipo-trademark-classification",\n    family: "GOODS_SERVICES_ID",\n    displayName: "Malaysia MyIPO Pre-Approved Goods and Services Classification",\n    canonicalUri: "https://onlineapps.myipo.gov.my/tmclass/search_class.php",\n    entrypoints: [\n      { uri: "https://onlineapps.myipo.gov.my/tmclass/search_class.php", label: "Pre-approved goods and services class search" },\n      { uri: "https://www.myipo.gov.my/applying-for-a-trademark/", label: "Nice Classification guidance" },\n    ],\n    mode: "MIXED",\n    renderJavascriptHint: true,\n    expectedArtifactKinds: ["HTML", "JSON"],\n    verificationEvidenceUri: "https://www.myipo.gov.my/applying-for-a-trademark/",\n    notes: "MyIPO provides a searchable pre-approved goods/services database and official Nice-classification guidance for trademark specifications.",\n  }),\n'''
